//https://atcoder.jp/contests/abc228/tasks/abc228_d



#include<iostream>
#include<set>
#include<vector>

using namespace std;

typedef long long ll;

const int MAXN = 1 << 20;
int fa[MAXN];
ll v[MAXN];

int find(int x) {
    if (fa[x] != x)
        fa[x] = find(fa[x]);
    return fa[x];
}

void solve() {
    int q;
    cin >> q;

    
    for (int i = 0; i < MAXN; ++i) {
        fa[i] = i;
        v[i] = -1;
    }

    while (q--) {
        int op;
        ll x;
        cin >> op >> x;

        int h = x % MAXN;

        if (op == 1) {
            int p = find(h);
            v[p] = x;
            fa[p] = find((p + 1) % MAXN) ;
        }
        else 
            cout << v[h] << "\n";
        
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();

    return 0;
}

