        int t; long long x;
        cin >> t >> x;
        if (t == 1) {
            int pos = find(x % N);
            A[pos] = x;
            parent[pos] = find(pos + 1);
        } else {
            cout << A[x % N] << '\n';
        }
    }
    return 0;
}

