#include<bits/stdc++.h>

using namespace std;

void solve() {
    int n, m;
    cin >> n >> m;

    map<int, int> mpb, mpw;

    for (int i = 0; i < m; i++) {
        int x, y;
        char c;
        cin >> x >> y >> c;

        if (c == 'B') {
            if (mpb.find(x) == mpb.end()) {
                mpb[x] = y;
            } else {
                mpb[x] = max(mpb[x], y);
            }
        } else {
            if (mpw.find(x) == mpw.end()) {
                mpw[x] = y;
            } else {
                mpw[x] = min(mpw[x], y);
            }
        }
    }
    bool ans = true;
    if (mpb.empty() || mpw.empty()) {
        cout << "Yes";
        return;
    }

    auto bit = mpb.rbegin();
    int rst = -1;
    for (auto it = mpw.rbegin(); it != mpw.rend(); it++) {
        while (bit != mpb.rend() && bit->first >= it->first) {
            rst = max(rst, bit->second);
            bit++;
        }
        if (rst >= it->second) {
            ans = false;
            break;
        }
    }
    if (ans) {
        cout << "Yes";
    } else {
        cout << "No";
    }
}

int main() {
#ifdef LOCAL
    freopen("input.txt", "r", stdin);
#endif

    solve();

    return 0;
}

