#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int n;
        cin >> n;
        string s;
        cin >> s;
        long long inv = 0;
        int ones = 0;
        for (char c : s) {
            if (c == '1') ones++;
            else inv += ones;
        }
        if (inv % 2 == 1) {
            cout << "Alice\n";
            continue;
        }
        vector<int> suf0(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) {
            suf0[i] = suf0[i + 1] + (s[i] == '0');
        }
        bool ok = false;
        int pref1 = 0;
        for (int i = 0; i < n; i++) {
            if (s[i] == '1') pref1++;
            if (pref1 % 2 == 1 && (suf0[i + 1] % 2 == 1)) {
                ok = true;
                break;
            }
        }
        cout << (ok ? "Alice" : "Bob") << "\n";
    }
    return 0;
}

