int main(){

    long long n, m; scanf("%lld %lld", &n, &m);
    std::vector<bool> binary(n); std::vector<int> perm(n);
    int l(0), r(n - 1); --m;
    for(int p = n - 2; p >= 0; p--){binary[p] = m % 2; m /= 2;}
