#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
struct BIT {
    int m; vector<ll> cnt, sum;
    BIT(int n): m(n), cnt(n+1), sum(n+1) {}
    void add(int i, ll v) { while(i<=m){cnt[i]++; sum[i]+=v; i+=i&-i;} }
    ll get_cnt(int i){ll s=0;while(i>0){s+=cnt[i];i-=i&-i;}return s;}
    ll get_sum(int i){ll s=0;while(i>0){s+=sum[i];i-=i&-i;}return s;}
};
int main(){
    ios::sync_with_stdio(false); cin.tie(0);
    int t; cin>>t;
    while(t--){
        int n; ll k; cin>>n>>k;
        vector<ll> l(n+1), r(n+1), len(n+1);
        for(int i=1;i<=n;i++) cin>>l[i];
        for(int i=1;i<=n;i++){ cin>>r[i]; len[i]=r[i]-l[i]+1; }
        ll tot_all=0; for(int i=1;i<=n;i++) tot_all+=len[i];
        if(tot_all<k){ cout<<-1<<'\n'; continue; }
        vector<ll> vals=len; sort(vals.begin(),vals.end());
        vals.erase(unique(vals.begin(),vals.end()),vals.end());
        int m=vals.size(); BIT bit(m); ll tot_bit=0, ans=4e18;
        for(int p=1;p<=n;p++){
            if(p>1){
                int idx=lower_bound(vals.begin(),vals.end(),len[p-1])-vals.begin()+1;
                bit.add(idx,len[p-1]); tot_bit+=len[p-1];
            }
            if(k<=len[p]){
                ans=min(ans, l[p]+k-1+2);
            } else {
                ll need=k-len[p]; if(tot_bit<need) continue;
                int cnt=0; ll got=0; int idx=m;
                while(idx>0){
                    int nxt=idx-(idx&-idx);
                    ll bs=bit.get_sum(idx)-bit.get_sum(nxt);
                    ll bc=bit.get_cnt(idx)-bit.get_cnt(nxt);
                    if(got+bs<need){ got+=bs; cnt+=bc; idx=nxt; }
                    else { ll nm=need-got; ll v=vals[idx-1]; cnt+=(nm+v-1)/v; break; }
                }
                ans=min(ans, r[p]+2+2LL*cnt);
            }
        }
        cout<<ans<<'\n';
    }
}

