using namespace std;
int parent[1005];
int sz[1005];
bool hasGov[1005];
int find(int x){return parent[x]==x?x:parent[x]=find(parent[x]);}
void unite(int x,int y){x=find(x);y=find(y);if(x==y)return;if(sz[x]<sz[y])swap(x,y);parent[y]=x;sz[x]+=sz[y];hasGov[x]=hasGov[x]||hasGov[y];}
int main(){
    int n,m,k;cin>>n>>m>>k;
    for(int i=1;i<=n;i++){parent[i]=i;sz[i]=1;hasGov[i]=false;}
    for(int i=0;i<k;i++){int c;cin>>c;hasGov[find(c)]=true;}
    for(int i=0;i<m;i++){int u,v;cin>>u>>v;unite(u,v);}
    vector<int> govSizes;
    int freeNodes=0;
    for(int i=1;i<=n;i++){
        if(find(i)==i){
            if(hasGov[i]) govSizes.push_back(sz[i]);
            else freeNodes += sz[i];
        }
    }
    int maxGov=0;
    for(int s:govSizes){ if(s>maxGov) maxGov=s; }
    long long sumOther=0;
    for(int s:govSizes){ if(s!=maxGov) sumOther += (long long)s*(s-1)/2; }
    long long total = (long long)(maxGov+freeNodes)*(maxGov+freeNodes-1)/2 + sumOther;
    long long ans = total - m;
    cout<<ans<<endl;
    return 0;
}

