int main() {
    int n;
    long long m;
    if (!(cin >> n >> m)) return 0;
    vector<long long> a(n + 1);
    long long cnt = 0;
    int k = 0;
    for (int i = 1; i <= n; ++i) {
        long long add = (i - 1) / 2;
        if (cnt + add <= m) {
            cnt += add;
            a[i] = i;
            k = i;
        } else {
            break;
        }
    }
    if (k == n) {
        if (cnt < m) {
            cout << -1 << "\n";
            return 0;
        }
        for (int i = 1; i <= n; ++i) cout << a[i] << (i == n ? "\n" : " ");
        return 0;
    }
    long long need = m - cnt;
    long long d = (k / 2) - need;
    a[k + 1] = k + 1 + d;
    long long cur = a[k + 1] + 10000;
    for (int i = k + 2; i <= n; ++i) {
        a[i] = cur;
        cur += 10000;
    }
    for (int i = 1; i <= n; ++i) cout << a[i] << (i == n ? "\n" : " ");
    return 0;
}

