#include <bits/stdc++.h>
using namespace std;

using ll = int64_t;
void solve(){
	int N;
	cin >> N;
	vector<ll> C(N);
	ll ans = 0;
	ll singles = 0;

	ll tot = 0;

	ll extra = 0;
	for(int i = 0; i < N; i++){
		cin >> C[i];
		tot += C[i];
		if(C[i] >= 2){
			ans += C[i];
			extra += (C[i] - 2) / 2;
		} else {
			singles++;
		}
	}
	ans += min(singles, extra);
	ll other = min(tot, C[N-1] + C[N-1] / 2);
	ans = max(ans, other);
	if(ans < 3) ans = 0;
	cout << ans << '\n';
}

int main(){
	ios_base::sync_with_stdio(false), cin.tie(nullptr);
	int T;
	cin >> T;
	while(T--) solve();
}

