        for (int i = 0; i < n; i++) cin >> c[i];
        if (n == 1) {
            if (c[0] >= 3) cout << c[0] << "\n";
            else cout << "0\n";
            continue;
        }
        long long M = c[n-1];
        int k = min(n-1, (int)(M/2));
        long long sum = 0;
        for (int i = 0; i < k; i++) sum += c[n-2-i];
        long long ans = M + sum;
        if (ans < 3) ans = 0;
        cout << ans << "\n";
    }
    return 0;
}

