#include <iostream>
#include <string>
using namespace std;
using ull = unsigned long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ull n;
    int q;
    if (!(cin >> n >> q)) return 0;
    while (q--) {
        ull u;
        string s;
        cin >> u >> s;
        for (char c : s) {
            ull half = u & -u;
            if (c == 'U') {
                if (u + half <= n && (u + half) % (2 * half) == 0) {
                    u = u + half;
                } else if (u > half) {
                    u = u - half;
                }
            } else if (c == 'L') {
                if (half > 1) u -= half / 2;
            } else if (c == 'R') {
                if (half > 1) u += half / 2;
            }
        }
        cout << u << '\n';
    }
    return 0;
}

